int maxDegree(std::vector<int> const& A, size_t N) {
	std::vector<int> degrees(N);
	hpx::parallel::for_loop(hpx::parallel::execution::par, 0, N, [&A, &degrees](size_t i) {
		int degree = 0;
		for (size_t j = 0; j < N; j++) {
			if (A[i * N + j] == 1) {
				degree++;
			}
		}
		degrees[i] = degree;
	});
	return *std::max_element(degrees.begin(), degrees.end());
}

