   output: 2
*/
int componentCount(std::vector<int> const& A, size_t N) {

generated_output:
int componentCount(std::vector<int> const& A, size_t N) {
	std::vector<int> visited(N, 0);
	int count = 0;
	for (size_t i = 0; i < N; i++) {
		if (visited[i] == 0) {
			count++;
			std::vector<int> queue;
			queue.push_back(i);
			while (!queue.empty()) {
				int node = queue.back();
				queue.pop_back();
				if (visited[node] == 0) {
					visited[node] = 1;
					for (size_t j = 0; j < N; j++) {
						if (A[node * N + j] == 1) {
							queue.push_back(j);
						}
					}
				}
			}
		}
	}
	return count;
}

