	int count = 0;
	for (size_t i = 0; i < N; i++) {
		if (visited[i] == 0) {
			count++;
			hpx::future<void> f = hpx::async(
				[&](size_t i, std::vector<int> const& A, size_t N, std::vector<int>& visited) {
					std::queue<size_t> q;
					q.push(i);
					while (!q.empty()) {
						size_t v = q.front();
						q.pop();
						visited[v] = 1;
						for (size_t j = 0; j < N; j++) {
							if (A[v * N + j] == 1 && visited[j] == 0) {
